def components(cells):
    cells=set(cells); seen=set(); comps=[]
    for c in cells:
        if c in seen: continue
        stack=[c]; comp=[]
        seen.add(c)
        while stack:
            r,cc=stack.pop(); comp.append((r,cc))
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                n=(r+dr,cc+dc)
                if n in cells and n not in seen:
                    seen.add(n); stack.append(n)
        comps.append(comp)
    return comps

def extract_rects(grid):
    g=[row[:] for row in grid]; H=len(g); W=len(g[0]); rects=[]
    while True:
        pos=None
        for r in range(H):
            for c in range(W):
                if g[r][c]==8: pos=(r,c); break
            if pos: break
        if not pos: break
        r0,c0=pos
        c1=c0
        while c1+1<W and g[r0][c1+1]==8: c1+=1
        r1=r0
        while r1+1<H and all(g[r1+1][c]==8 for c in range(c0,c1+1)): r1+=1
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): g[r][c]=0
        rects.append((r0,c0,r1,c1))
    return rects

def transform(grid):
    g=[row[:] for row in grid]; H=len(g); W=len(g[0])
    rects=extract_rects(g)
    # key strokes: per-color connected components among cells !=0 and !=8
    key=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c] not in (0,8)]
    bycol={}
    for r,c,v in key: bycol.setdefault(v,[]).append((r,c))
    strokes=[]
    for v,cells in bycol.items():
        for comp in components(cells):
            strokes.append((len(comp), v))
    # sort blocks: area desc, then reading order
    rects.sort(key=lambda t:(-( (t[2]-t[0]+1)*(t[3]-t[1]+1) ), t[0], t[1]))
    # sort strokes: length desc, then color asc
    strokes.sort(key=lambda t:(-t[0], t[1]))
    out=[row[:] for row in grid]
    for (r0,c0,r1,c1),(L,v) in zip(rects,strokes):
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=v
    return out, rects, strokes

